class LinkedList:
    head = None

    def iter(self):
        curr = self.head
        while curr:
            yield curr
            curr = curr.next_node

    def delete(self, node):
        if self.head == node:
            self.head = self.head.next_node
            return

        prev = self.head
        while prev.next_node != node:
            prev = prev.next_node

        prev.next_node = node.next_node

    # Amortized O(1)
    def append(self, data):
        new_node = Node(data)

        if self.head == None:
            self.head = new_node
            return

        last_node = None
        for node in self.iter():
            last_node = node

        last_node.next_node = new_node

    def __len__(self):
        count = 0
        for _ in self.iter():
            count += 1
        return count



